/**
 * Renders model output as formatted text (ADR-026).
 *
 * Every node here is a React element built from a parsed structure — there is
 * no `dangerouslySetInnerHTML` and no HTML string anywhere in this path, so
 * model output cannot become markup no matter what it contains (§13.1).
 *
 * Links are shown with their URL as inert text rather than as anchors: a
 * clickable link generated by a language model, inside a Word task pane, is a
 * phishing vector for no real benefit.
 */
import type { ReactElement, ReactNode } from 'react';
import { Text, makeStyles, tokens } from '@fluentui/react-components';
import type { InlineNode, MarkdownBlock } from '../../../utils/markdown';
import { parseMarkdown } from '../../../utils/markdown';

const useStyles = makeStyles({
  root: {
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalS,
    overflowWrap: 'anywhere',
  },
  h1: { fontSize: tokens.fontSizeBase500, fontWeight: tokens.fontWeightSemibold },
  h2: { fontSize: tokens.fontSizeBase400, fontWeight: tokens.fontWeightSemibold },
  h3: { fontSize: tokens.fontSizeBase300, fontWeight: tokens.fontWeightSemibold },
  paragraph: { whiteSpace: 'pre-wrap' },
  code: {
    fontFamily: tokens.fontFamilyMonospace,
    fontSize: tokens.fontSizeBase200,
    backgroundColor: tokens.colorNeutralBackground3,
    padding: tokens.spacingHorizontalS,
    borderRadius: tokens.borderRadiusSmall,
    whiteSpace: 'pre-wrap',
    margin: 0,
  },
  inlineCode: {
    fontFamily: tokens.fontFamilyMonospace,
    backgroundColor: tokens.colorNeutralBackground3,
    borderRadius: tokens.borderRadiusSmall,
    padding: `0 ${tokens.spacingHorizontalXXS}`,
  },
  quote: {
    borderLeft: `3px solid ${tokens.colorNeutralStroke2}`,
    paddingLeft: tokens.spacingHorizontalS,
    color: tokens.colorNeutralForeground2,
  },
  list: { margin: 0, paddingLeft: tokens.spacingHorizontalXL },
  rule: { border: 'none', borderTop: `1px solid ${tokens.colorNeutralStroke2}`, width: '100%' },
  url: { color: tokens.colorNeutralForeground3 },
});

function Inline({ nodes }: { nodes: InlineNode[] }): ReactElement {
  const styles = useStyles();
  return (
    <>
      {nodes.map((node, index) => {
        const key = `${node.type}-${String(index)}`;
        switch (node.type) {
          case 'strong':
            return <strong key={key}>{node.value}</strong>;
          case 'em':
            return <em key={key}>{node.value}</em>;
          case 'code':
            return (
              <code key={key} className={styles.inlineCode}>
                {node.value}
              </code>
            );
          case 'link':
            return (
              <span key={key}>
                {node.value} <span className={styles.url}>({node.href})</span>
              </span>
            );
          case 'text':
            return <span key={key}>{node.value}</span>;
        }
      })}
    </>
  );
}

function Block({ block }: { block: MarkdownBlock }): ReactNode {
  const styles = useStyles();
  switch (block.type) {
    case 'heading': {
      const cls = block.level === 1 ? styles.h1 : block.level === 2 ? styles.h2 : styles.h3;
      return (
        <div className={cls}>
          <Inline nodes={block.inline} />
        </div>
      );
    }
    case 'paragraph':
      return (
        <Text className={styles.paragraph}>
          <Inline nodes={block.inline} />
        </Text>
      );
    case 'code':
      return <pre className={styles.code}>{block.value}</pre>;
    case 'quote':
      return (
        <div className={styles.quote}>
          <Inline nodes={block.inline} />
        </div>
      );
    case 'list': {
      const items = block.items.map((item, index) => (
        <li key={String(index)}>
          <Inline nodes={item} />
        </li>
      ));
      return block.ordered ? (
        <ol className={styles.list}>{items}</ol>
      ) : (
        <ul className={styles.list}>{items}</ul>
      );
    }
    case 'rule':
      return <hr className={styles.rule} />;
  }
}

export interface MarkdownViewProps {
  text: string;
}

export function MarkdownView({ text }: MarkdownViewProps): ReactElement {
  const styles = useStyles();
  const blocks = parseMarkdown(text);
  return (
    <div className={styles.root}>
      {blocks.map((block, index) => (
        <Block key={`${block.type}-${String(index)}`} block={block} />
      ))}
    </div>
  );
}
